    email      TEXT NOT NULL,
    created_at TEXT NOT NULL
, role TEXT NOT NULL DEFAULT 'member');
CREATE TABLE orders (
    id           INTEGER PRIMARY KEY,
    user_id      INTEGER NOT NULL REFERENCES users_v2(id),
    amount_cents INTEGER NOT NULL,
    status       TEXT NOT NULL,
    created_at   TEXT NOT NULL
);
